package lucid.core.model

import kotlinx.serialization.Serializable

/** Where a session's measurements came from. Every stored session and statistic carries this. */
@Serializable
enum class DataOrigin(val label: String) {
    /** Generated by the in-app or on-watch simulator. Never evidence of real physiology. */
    SIMULATED("Simulated"),

    /** A previously recorded file replayed through the pipeline. */
    REPLAYED("Replayed"),

    /** Live measurements from a physical watch. */
    REAL_DEVICE("Real watch"),
}

@Serializable
data class SourceInfo(
    val origin: DataOrigin,
    /** Human-readable device, e.g. "Galaxy Watch7 (SM-L300)" or "In-app simulator". */
    val device: String,
    /** Sensor provider id, e.g. "sim", "android-sensors", "samsung-health-sensor". */
    val provider: String,
    val scenarioId: String? = null,
    val seed: Long? = null,
) {
    val isSimulated: Boolean get() = origin == DataOrigin.SIMULATED
}

/** Source of "now". Simulations swap in a virtual clock that runs faster than real time. */
fun interface Clock {
    fun nowMs(): Long

    companion object {
        val System = Clock { java.lang.System.currentTimeMillis() }
    }
}
